import React from 'react';
import {Linking,Pressable,StyleSheet,Text,View} from '@/platform/react-native';
import {router,useLocalSearchParams} from '@/router';
import {useMutation,useQuery,useQueryClient} from '@tanstack/react-query';
import {Ionicons} from '@/platform/icons';
import {api} from '@/lib/api';
import {Badge,Button,Card,EmptyState,Muted,Screen,TabBar,useAppTheme} from '@/components/UI';
import type {Meeting} from '@/types';

type MeetingRecord=Meeting&{CommunityId:string;OnlineMeetingUrl?:string;Agenda?:string};
type Tab='upcoming'|'past';

export default function GeneralMeetings(){
 const{id}=useLocalSearchParams<{id:string}>();const{palette}=useAppTheme();const qc=useQueryClient();
 const[tab,setTab]=React.useState<Tab>('upcoming');
 const meetings=useQuery<MeetingRecord[]>({queryKey:['meetings',id],queryFn:async()=>(await api.get(`/communities/${id}/meetings`)).data,enabled:!!id});
 const rsvp=useMutation({mutationFn:async(v:{meetingId:string;response:'GOING'|'MAYBE'|'NOT_GOING'})=>api.post(`/meetings/${v.meetingId}/rsvp`,{response:v.response}),onSuccess:()=>qc.invalidateQueries({queryKey:['meetings',id]})});
 const now=Date.now();const sorted=[...(meetings.data||[])].sort((a,b)=>new Date(a.StartDateTime).getTime()-new Date(b.StartDateTime).getTime());
 const visible=sorted.filter(m=>tab==='upcoming'?new Date(m.EndDateTime||m.StartDateTime).getTime()>=now:new Date(m.EndDateTime||m.StartDateTime).getTime()<now);
 const upcomingCount=sorted.filter(m=>new Date(m.EndDateTime||m.StartDateTime).getTime()>=now).length;
 return <Screen scroll contentStyle={s.screen}>
  <Card style={[s.intro,{borderColor:palette.primarySoft}]}><View style={[s.introIcon,{backgroundColor:palette.primarySoft}]}><Ionicons name="people-circle-outline" size={34} color={palette.primary}/></View><View style={{flex:1}}><Text style={[s.introTitle,{color:palette.primary}]}>Community decisions start here</Text><Muted>Review meeting details, respond to invitations and revisit completed meetings.</Muted></View></Card>
  <TabBar value={tab} onChange={setTab} items={[{key:'upcoming',label:'Upcoming Meetings',icon:'calendar-outline',count:upcomingCount},{key:'past',label:'Past Meetings',icon:'time-outline',count:sorted.length-upcomingCount}]}/>
  <View style={s.sectionHead}><View><Text style={[s.sectionTitle,{color:palette.text}]}>{tab==='upcoming'?'Upcoming Meetings':'Past Meetings'}</Text><Muted>{tab==='upcoming'?'Meetings scheduled for your community':'Completed community meeting history'}</Muted></View><Ionicons name={tab==='upcoming'?'calendar-outline':'time-outline'} size={24} color={palette.primary}/></View>
  {meetings.isError?<EmptyState icon="cloud-offline-outline" title="Could not load meetings" body="Check your connection, then try again."/>:visible.length?visible.map(meeting=><MeetingCard key={meeting.Id} meeting={meeting} past={tab==='past'} busy={rsvp.isPending} onRsvp={response=>rsvp.mutate({meetingId:meeting.Id,response})} palette={palette}/>):<EmptyState icon={tab==='upcoming'?'calendar-outline':'archive-outline'} title={tab==='upcoming'?'No upcoming meetings':'No past meetings'} body={tab==='upcoming'?'New general meetings created by community administrators will appear here.':'Completed meetings will be kept here for reference.'}/>}
 </Screen>
}


function MeetingCard({meeting,past,busy,onRsvp,palette}:{meeting:MeetingRecord;past:boolean;busy:boolean;onRsvp:(response:'GOING'|'MAYBE'|'NOT_GOING')=>void;palette:any}){
 const start=new Date(meeting.StartDateTime);const end=new Date(meeting.EndDateTime);const response=meeting.MyResponse;
 return <Card style={s.card}><Pressable accessibilityRole="button" accessibilityLabel={`Open ${meeting.Title}`} onPress={()=>router.push(`/community/${meeting.CommunityId}/meeting/${meeting.Id}` as any)}><View style={s.cardTop}><View style={[s.date,{backgroundColor:past?palette.backgroundSoft:palette.primarySoft}]}><Text style={[s.month,{color:past?palette.muted:palette.primary}]}>{start.toLocaleString(undefined,{month:'short'}).toUpperCase()}</Text><Text style={[s.day,{color:palette.text}]}>{start.getDate()}</Text><Text style={[s.year,{color:palette.muted}]}>{start.getFullYear()}</Text></View><View style={{flex:1}}><View style={s.titleRow}><Text style={[s.title,{color:palette.text}]}>{meeting.Title}</Text><Badge text={past?'Completed':response?response.replace('_',' '):'RSVP'} tone={past?'gray':response==='GOING'?'green':response==='NOT_GOING'?'red':'orange'}/></View><Info icon="time-outline" text={`${start.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})} – ${end.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}`} palette={palette}/><Info icon={meeting.OnlineMeetingUrl?'videocam-outline':'location-outline'} text={meeting.OnlineMeetingUrl?'Online meeting':meeting.Location||'Location to be confirmed'} palette={palette}/>{meeting.MeetingType?<Info icon="people-outline" text={meeting.MeetingType} palette={palette}/>:null}<View style={s.detailsLink}><Text style={{color:palette.primary,fontWeight:'900'}}>View meeting details</Text><Ionicons name="chevron-forward" size={18} color={palette.primary}/></View></View></View></Pressable>{meeting.Description?<Text style={[s.description,{color:palette.text}]}>{meeting.Description}</Text>:null}{meeting.Agenda?<View style={[s.agenda,{backgroundColor:palette.backgroundSoft}]}><Ionicons name="list-outline" size={18} color={palette.primary}/><Text style={{color:palette.text,flex:1}} numberOfLines={3}>{meeting.Agenda}</Text></View>:null}{!past?<View style={s.actions}><Button title="Going" variant={response==='GOING'?'success':'secondary'} disabled={busy} onPress={()=>onRsvp('GOING')}/><Button title="Maybe" variant={response==='MAYBE'?'success':'secondary'} disabled={busy} onPress={()=>onRsvp('MAYBE')}/><Button title="Can't go" variant="ghost" disabled={busy} onPress={()=>onRsvp('NOT_GOING')}/></View>:null}{!past&&meeting.OnlineMeetingUrl?<Button title="Join online meeting" icon="videocam-outline" onPress={()=>Linking.openURL(meeting.OnlineMeetingUrl!)}/>:null}</Card>
}
function Info({icon,text,palette}:{icon:keyof typeof Ionicons.glyphMap;text:string;palette:any}){return <View style={s.info}><Ionicons name={icon} size={16} color={palette.primary}/><Muted style={{flex:1}}>{text}</Muted></View>}

const s=StyleSheet.create({screen:{maxWidth:920,paddingBottom:28},intro:{flexDirection:'row',alignItems:'center',gap:13,borderWidth:1},introIcon:{width:58,height:58,borderRadius:29,alignItems:'center',justifyContent:'center'},introTitle:{fontSize:16,fontWeight:'900',marginBottom:4},tabs:{flexDirection:'row',padding:4,borderRadius:15,borderWidth:1,marginVertical:14},tab:{flex:1,minHeight:45,borderRadius:11,flexDirection:'row',alignItems:'center',justifyContent:'center',gap:7,paddingHorizontal:7},tabText:{fontSize:12,fontWeight:'900',textAlign:'center'},count:{minWidth:22,height:22,borderRadius:11,alignItems:'center',justifyContent:'center',paddingHorizontal:5},sectionHead:{flexDirection:'row',justifyContent:'space-between',alignItems:'center',marginBottom:10},sectionTitle:{fontSize:18,fontWeight:'900'},card:{gap:13},cardTop:{flexDirection:'row',gap:12},date:{width:64,height:78,borderRadius:14,alignItems:'center',justifyContent:'center'},month:{fontSize:11,fontWeight:'900'},day:{fontSize:25,fontWeight:'900'},year:{fontSize:10,fontWeight:'700'},titleRow:{flexDirection:'row',alignItems:'flex-start',justifyContent:'space-between',gap:8,marginBottom:5},title:{fontSize:16,fontWeight:'900',flex:1},info:{flexDirection:'row',alignItems:'center',gap:7,marginTop:5},detailsLink:{flexDirection:'row',alignItems:'center',gap:4,marginTop:9},description:{fontSize:14,lineHeight:21},agenda:{flexDirection:'row',gap:8,padding:11,borderRadius:11},actions:{flexDirection:'row',gap:7,flexWrap:'wrap'}});
